	t.Run("positive", func(t *testing.T) {
		if got := Negate(4); got != -4 {
			t.Fatalf("Negate(4) = %d, want -4", got)
		}
	})
	t.Run("negative", func(t *testing.T) {
		if got := Negate(-3); got != 3 {
			t.Fatalf("Negate(-3) = %d, want 3", got)
		}
	})
}
